      <div className="min-w-[220px] flex-1"><label className="filter-label">Search products</label><div className="relative mt-1.5"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-slate-400" /><Input value={filters.search} onChange={(event) => update("search", event.target.value)} placeholder="Product, SKU or style" className="rounded-xl border-slate-200 bg-white pl-9" /></div></div>
