      <FieldSelect label="Changes since" value={filters.changeWindow} onValueChange={(value) => update("changeWindow", value)} options={[{ value: "all", label: "Any time" }, { value: "latest", label: "Latest scan" }, { value: "7", label: "Last 7 days" }, { value: "30", label: "Last 30 days" }]} />
